"""Export the optimized CSS: average the CSS generated by a trained online model over the
validation images (Section 4.3.2, Fig. 7). The result is a [K, 31] array whose rows are
L1-normalized curves on the 31 bands 400:10:700 nm.

    python export_css.py --checkpoint best_ema.pth --data_root /path/to/ARAD_1K --out css/my_css.npy
"""
import argparse
import os

import numpy as np
import torch

from hsi_data import FullImageDataset
from models import build_online_model, load_weights


def get_args():
    p = argparse.ArgumentParser(description="Export the averaged optimized CSS")
    p.add_argument("--checkpoint", required=True)
    p.add_argument("--data_root", required=True)
    p.add_argument("--dataset", default="arad", choices=["arad", "cave"])
    p.add_argument("--part", default="val", choices=["val", "test"])
    p.add_argument("--num_channels", type=int, default=4)
    p.add_argument("--poly_degree", type=int, default=4)
    p.add_argument("--out", default="css/exported_css.npy")
    return p.parse_args()


@torch.no_grad()
def main():
    args = get_args()
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = build_online_model(args.num_channels, args.poly_degree, pretrained_backbone=False)
    load_weights(model, args.checkpoint, device)
    model.to(device).eval()

    curves = []
    for hsi in FullImageDataset(args.data_root, args.dataset, part=args.part):
        model(hsi.unsqueeze(0).to(device))          # full image, single forward, fp32
        curves.append(model.css[0].cpu().numpy())   # [K, 31]
    curves = np.stack(curves)                       # [N, K, 31]
    css = curves.mean(axis=0).astype(np.float32)

    os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
    np.save(args.out, css)
    np.save(os.path.splitext(args.out)[0] + "_per_image.npy", curves)
    wl = np.arange(400, 701, 10)
    for k, c in enumerate(css, 1):
        print(f"CSS-{k}: peak {wl[c.argmax()]} nm, sum {c.sum():.6f}")
    print(f"Saved {args.out} (averaged over {len(curves)} images)")


if __name__ == "__main__":
    main()
